133	    // The workroom-into-workroom split groups (issue #23). A leaf whose workroom is gone collapses,
134	    // and a group left with fewer than two leaves dissolves — `materialize` enforces that, so a
135	    // one-workroom "group" can never reach the live model.
136	    workroomSplits = session.workroomSplits.compactMap { saved in
137	      saved.materialize { Self.sidebarID(forTargetID: $0, in: projects) }
138	    }
139	    // Sidebar terminal-subtree expansion (issue #30). Only for targets that actually came back —
140	    // an expand flag pointing at nothing would render an empty disclosure.
141	    expandedTerminalTargets = Set(session.expandedTargets ?? []).intersection(restoredTargetIDs)
142	
143	    refreshSelectionHasTabs()
144	  }
