662	  /// Clamp every free-form string. One giant path in an otherwise sane file is exactly what the
663	  /// element caps cannot catch.
664	  fileprivate func clamped() -> TabSession {
665	    func clamp(_ value: String) -> String { String(value.prefix(SessionLimits.maxStringLength)) }
666	    func clamp(_ value: String?) -> String? { value.map(clamp) }
667	
668	    var tab = self
669	    tab.key = clamp(key)
670	    tab.kind = clamp(kind)
671	    if var terminal = tab.terminal {
672	      terminal.defaultTitle = clamp(terminal.defaultTitle)
673	      terminal.cwd = clamp(terminal.cwd)
674	      tab.terminal = terminal
675	    }
676	    if var diff = tab.diff {
677	      diff.path = clamp(diff.path)
678	      diff.source.commit = clamp(diff.source.commit)
679	      tab.diff = diff
680	    }
681	    if var file = tab.file {
682	      file.path = clamp(file.path)
683	      tab.file = file
684	    }
685	    if var changeset = tab.changeset {
686	      changeset.commitID = clamp(changeset.commitID)
687	      changeset.title = clamp(changeset.title)
688	      changeset.selectedPath = clamp(changeset.selectedPath)
689	      tab.changeset = changeset
690	    }
691	    return tab
692	  }
